#!/bin/sh
# Host-side tests for the device-tree parser, allocator reservation logic and physical-target mapping policy.
# Needs only a C compiler. Built with AddressSanitizer + UBSan.
set -e
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$ROOT/build/host-tests"
mkdir -p "$OUT"
cd "$ROOT"   # a few tests read repository files (generated font header, licence notices) by relative path
CFLAGS="-std=c11 -Wall -Wextra -Werror -O1 -g -fsanitize=address,undefined -fno-sanitize-recover=undefined -I $ROOT/kernel/include"
cc $CFLAGS -o "$OUT/fdt_pmm_test" "$ROOT/tests/kernel-host/fdt_pmm_test.c" "$ROOT/kernel/mm/fdt.c" "$ROOT/kernel/mm/pmm.c"
cc $CFLAGS -o "$OUT/policy_test" "$ROOT/tests/kernel-host/policy_test.c" "$ROOT/kernel/mm/mmpolicy.c"
cc $CFLAGS -o "$OUT/elf_test" "$ROOT/tests/kernel-host/elf_test.c" "$ROOT/kernel/proc/elf.c"
cc $CFLAGS -o "$OUT/fwcfg_test" "$ROOT/tests/kernel-host/fwcfg_test.c" "$ROOT/kernel/drivers/fwcfg_proto.c"
cc $CFLAGS -o "$OUT/gfx_test" "$ROOT/tests/kernel-host/gfx_test.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_region.c"
cc $CFLAGS -o "$OUT/gfx_shape_test" "$ROOT/tests/kernel-host/gfx_shape_test.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c"
cc $CFLAGS -o "$OUT/gfx_text_test" "$ROOT/tests/kernel-host/gfx_text_test.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/input_test" "$ROOT/tests/kernel-host/input_test.c" "$ROOT/kernel/input/input_core.c"
cc $CFLAGS -o "$OUT/ui_focus_test" "$ROOT/tests/kernel-host/ui_focus_test.c" "$ROOT/kernel/input/ui_focus.c"
cc $CFLAGS -o "$OUT/ui_scene_test" "$ROOT/tests/kernel-host/ui_scene_test.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_test" "$ROOT/tests/kernel-host/shell_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_scale_test" "$ROOT/tests/kernel-host/shell_scale_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c" -lm
cc $CFLAGS -o "$OUT/shell_settings_test" "$ROOT/tests/kernel-host/shell_settings_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_pages_test" "$ROOT/tests/kernel-host/shell_pages_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_clock_test" "$ROOT/tests/kernel-host/shell_clock_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_trail_test" "$ROOT/tests/kernel-host/shell_trail_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/shell_apps_test" "$ROOT/tests/kernel-host/shell_apps_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc -std=c11 -Wall -Wextra -Werror -O1 -g -fsanitize=address,undefined -o "$OUT/calc_test" "$ROOT/tests/kernel-host/calc_test.c"
cc $CFLAGS -o "$OUT/shell_review_test" "$ROOT/tests/kernel-host/shell_review_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c" -lm
cc $CFLAGS -o "$OUT/shell_aura_test" "$ROOT/tests/kernel-host/shell_aura_test.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/aura_exec.c" "$ROOT/kernel/ui/broker_policy.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c"
cc $CFLAGS -o "$OUT/procsnap_test" "$ROOT/tests/kernel-host/procsnap_test.c" "$ROOT/kernel/proc/procsnap.c"
cc $CFLAGS -o "$OUT/ui_proto_test" "$ROOT/tests/kernel-host/ui_proto_test.c" "$ROOT/kernel/ui/ui_proto.c"
cc $CFLAGS -o "$OUT/aura_cmd_test" "$ROOT/tests/kernel-host/aura_cmd_test.c" "$ROOT/kernel/ui/aura_cmd.c"
cc $CFLAGS -o "$OUT/broker_policy_test" "$ROOT/tests/kernel-host/broker_policy_test.c" "$ROOT/kernel/ui/broker_policy.c" "$ROOT/kernel/ui/aura_cmd.c"
cc $CFLAGS -o "$OUT/aura_exec_test" "$ROOT/tests/kernel-host/aura_exec_test.c" "$ROOT/kernel/ui/aura_exec.c" "$ROOT/kernel/ui/broker_policy.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c" -lm
cc $CFLAGS -o "$OUT/aura_s1_test" "$ROOT/tests/kernel-host/aura_s1_test.c" "$ROOT/kernel/ui/aura_exec.c" "$ROOT/kernel/ui/broker_policy.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c" -lm
cc $CFLAGS -o "$OUT/aura_timer_test" "$ROOT/tests/kernel-host/aura_timer_test.c" "$ROOT/kernel/ui/aura_exec.c" "$ROOT/kernel/ui/broker_policy.c" "$ROOT/kernel/ui/aura_cmd.c" "$ROOT/kernel/ui/shell.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/ui_proto.c" "$ROOT/kernel/proc/procsnap.c" "$ROOT/kernel/ui/index_model.c" "$ROOT/kernel/ui/ui_scene.c" "$ROOT/kernel/input/ui_focus.c" "$ROOT/kernel/gfx/gfx_draw.c" "$ROOT/kernel/gfx/gfx_shape.c" "$ROOT/kernel/gfx/gfx_text.c" "$ROOT/kernel/gfx/font_noto_mono.c" -lm
cc $CFLAGS -o "$OUT/passport_test" "$ROOT/tests/kernel-host/passport_test.c" "$ROOT/kernel/ui/passport.c"
cc $CFLAGS -o "$OUT/trail_test" "$ROOT/tests/kernel-host/trail_test.c" "$ROOT/kernel/ui/trail.c"
cc $CFLAGS -o "$OUT/index_model_test" "$ROOT/tests/kernel-host/index_model_test.c" "$ROOT/kernel/ui/index_model.c"
cc $CFLAGS -o "$OUT/timersvc_test" "$ROOT/tests/kernel-host/timersvc_test.c" "$ROOT/kernel/ui/timersvc.c"
cc $CFLAGS -o "$OUT/principal_test" "$ROOT/tests/kernel-host/principal_test.c"
cc $CFLAGS -o "$OUT/hold_test" "$ROOT/tests/kernel-host/hold_test.c" "$ROOT/kernel/ui/hold.c"
cc $CFLAGS -o "$OUT/review_test" "$ROOT/tests/kernel-host/review_test.c" "$ROOT/kernel/ui/review.c" "$ROOT/kernel/ui/aura_cmd.c"
cc $CFLAGS -o "$OUT/ledger_test" "$ROOT/tests/kernel-host/ledger_test.c" "$ROOT/kernel/ui/ledger_store.c" "$ROOT/kernel/ui/passport.c" "$ROOT/kernel/ui/trail.c"
"$OUT/fdt_pmm_test"
"$OUT/policy_test"
"$OUT/elf_test"
"$OUT/fwcfg_test"
"$OUT/gfx_test"
"$OUT/gfx_shape_test"
"$OUT/gfx_text_test"
"$OUT/input_test"
"$OUT/ui_focus_test"
"$OUT/ui_scene_test"
"$OUT/shell_test"
"$OUT/shell_scale_test"
"$OUT/shell_settings_test"
"$OUT/shell_pages_test"
"$OUT/shell_clock_test"
"$OUT/shell_trail_test"
"$OUT/shell_apps_test"
"$OUT/calc_test"
"$OUT/shell_review_test"
"$OUT/shell_aura_test"
"$OUT/procsnap_test"
"$OUT/ui_proto_test"
"$OUT/aura_cmd_test"
"$OUT/broker_policy_test"
"$OUT/aura_exec_test"
"$OUT/aura_s1_test"
"$OUT/aura_timer_test"
"$OUT/passport_test"
"$OUT/trail_test"
"$OUT/index_model_test"
python3 "$ROOT/tests/aura-eval/selftest.py"
"$OUT/timersvc_test"
"$OUT/principal_test"
"$OUT/hold_test"
"$OUT/review_test"
"$OUT/ledger_test"
